// Shared helpers for the "which code points get escaped" investigation.
import { run } from './drv.mjs';

// Parse a Python string literal starting at index i in s (s[i] is the quote char).
// Returns {raw, end} where raw is the literal INCLUDING quotes.
export function scanPyLiteral(s, i) {
  const q = s[i];
  if (q !== "'" && q !== '"') return null;
  let j = i + 1;
  while (j < s.length) {
    if (s[j] === '\\') { j += 2; continue; }
    if (s[j] === q) return { raw: s.slice(i, j + 1), body: s.slice(i + 1, j), quote: q, end: j + 1 };
    j++;
  }
  return null;
}

// Extract the old_value literal body (repr content between the quotes) from output.
export function oldValueBody(out) {
  const k = out.indexOf("'old_value': ");
  if (k < 0) return null;
  const lit = scanPyLiteral(out, k + "'old_value': ".length);
  return lit ? lit : null;
}

// The JS-side hypothesis predicate: true == printable (emitted literally).
export function jsPred(cp) {
  if (cp === 0x20) return true;
  return !/[\p{C}\p{Z}]/u.test(String.fromCodePoint(cp));
}

export function hex(cp) {
  return 'U+' + cp.toString(16).toUpperCase().padStart(4, '0');
}

// Separator char used to delimit batched code points. '.' is printable, never
// appears inside any Python escape sequence, and is not itself special in repr.
export const SEP = '.';

// Build one argument holding many code points, SEP-delimited.
export function buildArg(cps) {
  let s = SEP;
  for (const cp of cps) s += String.fromCodePoint(cp) + SEP;
  return s;
}

// Run one batch, return array of per-codepoint repr fragments (or null on misalign).
export function classifyBatch(cps) {
  const arg = buildArg(cps);
  const r = run(arg, 'MARKER');
  const lit = oldValueBody(r.out);
  if (!lit) return { error: 'unparsed', out: r.out, err: r.err };
  const parts = lit.body.split(SEP);
  // Expect ['', f0, f1, ..., fN-1, '']
  if (parts.length !== cps.length + 2 || parts[0] !== '' || parts[parts.length - 1] !== '') {
    return { error: 'misaligned', got: parts.length, want: cps.length + 2, body: lit.body };
  }
  return { quote: lit.quote, fields: parts.slice(1, -1) };
}

// Step 1: validate alignment method on known-good batches + spot-check semantics.
import { run } from './drv.mjs';
import { classifyBatch, jsPred, hex, oldValueBody } from './lib.mjs';

function show(label, cps) {
  const res = classifyBatch(cps);
  if (res.error) {
    console.log(`${label}: ERROR ${res.error}`, JSON.stringify(res).slice(0, 600));
    return;
  }
  console.log(`${label}: quote=${res.quote}`);
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i];
    const f = res.fields[i];
    const literal = f === String.fromCodePoint(cp);
    const pred = jsPred(cp);
    const agree = literal === pred;
    console.log(`  ${hex(cp)} field=${JSON.stringify(f)} literal=${literal} jsPred=${pred} ${agree ? '' : '<<< DISAGREE'}`);
  }
}

// A: pure-ASCII printable batch -- everything must come back literally.
const asciiPrintable = [];
for (let cp = 0x21; cp <= 0x7e; cp++) {
  if (cp === 0x2e || cp === 0x27 || cp === 0x22 || cp === 0x5c) continue;
  asciiPrintable.push(cp);
}
show('A ascii-printable', asciiPrintable);

// B: mixed known cases.
show('B mixed', [0x07, 0x1b, 0x7f, 0x20, 0xe9, 0xa0, 0xad, 0x378, 0x2028, 0x3000, 0x200b, 0x1f600]);

// C: the repr-special characters, probed one at a time (they change quote style).
for (const cp of [0x27, 0x22, 0x5c, 0x2e]) {
  const r = run(String.fromCodePoint(cp), 'MARKER');
  const lit = oldValueBody(r.out);
  console.log(`C ${hex(cp)} -> raw=${lit ? JSON.stringify(lit.raw) : 'UNPARSED'} body=${lit ? JSON.stringify(lit.body) : ''}`);
}

// D: can U+0000 even be passed?
{
  const r = run('a�b', 'MARKER');
  const lit = oldValueBody(r.out);
  console.log(`D NUL: code=${r.code} err=${JSON.stringify(r.err.slice(0, 300))} body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'}`);
}

// E: lone surrogates
for (const cp of [0xd800, 0xdfff]) {
  const s = String.fromCharCode(cp);
  const r = run('[' + s + ']', 'MARKER');
  const lit = oldValueBody(r.out);
  console.log(`E ${hex(cp)}: code=${r.code} body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'} err=${JSON.stringify(r.err.slice(0, 200))}`);
}

// F: what locale/encoding is in play -- does a 4-byte astral char survive?
{
  const r = run('[\u{1F600}\u{10FFFF}]', 'MARKER');
  const lit = oldValueBody(r.out);
  console.log(`F astral: body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'}`);
}

