// Namespaced helpers for the "which code points does repr() escape" dimension.
import { run } from './drv.mjs';

// Scan a Python string literal starting at index i (s[i] must be the quote char).
// Returns {raw, body, quote, end}. body is the RAW repr content (escapes NOT decoded).
export function scanPyLiteral(s, i) {
  const q = s[i];
  if (q !== "'" && q !== '"') return null;
  let j = i + 1;
  while (j < s.length) {
    if (s[j] === '\\') { j += 2; continue; }
    if (s[j] === q) return { raw: s.slice(i, j + 1), body: s.slice(i + 1, j), quote: q, end: j + 1 };
    j++;
  }
  return null;
}

const OV = "'old_value': ";
export function oldValueLit(out) {
  const k = out.indexOf(OV);
  if (k < 0) return null;
  return scanPyLiteral(out, k + OV.length);
}

// Hypothesis predicate: true == printable == emitted literally by repr().
export function jsPred(cp) {
  if (cp === 0x20) return true;
  return !/[\p{C}\p{Z}]/u.test(String.fromCodePoint(cp));
}

export function hex(cp) {
  const h = cp.toString(16).toUpperCase();
  return 'U+' + (h.length < 4 ? h.padStart(4, '0') : h);
}

export const SEP = '.';

export function buildArg(cps) {
  let s = SEP;
  for (const cp of cps) s += String.fromCodePoint(cp) + SEP;
  return s;
}

// Run one batch; return {fields:[...]} aligned with cps, or {error:...}.
export function classifyBatch(cps) {
  const r = run(buildArg(cps), 'MARKER');
  if (r.code !== 0) return { error: 'exit' + r.code, err: r.err.slice(-400) };
  const lit = oldValueLit(r.out);
  if (!lit) return { error: 'unparsed', out: r.out.slice(0, 400), err: r.err.slice(-300) };
  const parts = lit.body.split(SEP);
  if (parts.length !== cps.length + 2 || parts[0] !== '' || parts[parts.length - 1] !== '') {
    return { error: 'misaligned', got: parts.length, want: cps.length + 2, body: lit.body.slice(0, 400) };
  }
  return { quote: lit.quote, fields: parts.slice(1, -1) };
}

// Split a batch in half recursively when misaligned, so one bad code point
// does not poison the whole batch. Returns Map cp -> field | {error}.
export function classifyRobust(cps, out = new Map()) {
  if (cps.length === 0) return out;
  const res = classifyBatch(cps);
  if (!res.error) {
    for (let i = 0; i < cps.length; i++) out.set(cps[i], res.fields[i]);
    return out;
  }
  if (cps.length === 1) { out.set(cps[0], { error: res.error, detail: res }); return out; }
  const mid = cps.length >> 1;
  classifyRobust(cps.slice(0, mid), out);
  classifyRobust(cps.slice(mid), out);
  return out;
}

// Step 1: validate the alignment method + spot-check semantics.
import { run } from './drv.mjs';
import { classifyBatch, jsPred, hex, oldValueLit } from './esclib.mjs';

function show(label, cps) {
  const res = classifyBatch(cps);
  if (res.error) {
    console.log(`${label}: ERROR`, JSON.stringify(res).slice(0, 800));
    return;
  }
  let bad = 0;
  const notes = [];
  for (let i = 0; i < cps.length; i++) {
    const cp = cps[i], f = res.fields[i];
    const literal = f === String.fromCodePoint(cp);
    const pred = jsPred(cp);
    if (literal !== pred) { bad++; notes.push(`${hex(cp)} field=${JSON.stringify(f)} literal=${literal} jsPred=${pred}`); }
  }
  console.log(`${label}: quote=${res.quote} n=${cps.length} disagreements=${bad}`);
  for (const n of notes) console.log('   DISAGREE ' + n);
  return res;
}

// A: pure-ASCII printable batch -- everything must come back literally.
const asciiPrintable = [];
for (let cp = 0x21; cp <= 0x7e; cp++) {
  if (cp === 0x2e || cp === 0x27 || cp === 0x22 || cp === 0x5c) continue;
  asciiPrintable.push(cp);
}
const rA = show('A ascii-printable', asciiPrintable);
if (rA && rA.fields) console.log('   sample fields:', rA.fields.slice(0, 12).join(' '));

// B: mixed known cases -- print full detail.
{
  const cps = [0x07, 0x1b, 0x7f, 0x20, 0xe9, 0xa0, 0xad, 0x378, 0x2028, 0x3000, 0x200b, 0x1f600];
  const res = classifyBatch(cps);
  console.log('B mixed:', res.error ? JSON.stringify(res).slice(0, 600) : '');
  if (!res.error) for (let i = 0; i < cps.length; i++) {
    const cp = cps[i], f = res.fields[i];
    console.log(`  ${hex(cp)} field=${JSON.stringify(f)} literal=${f === String.fromCodePoint(cp)} jsPred=${jsPred(cp)}`);
  }
}

// C: repr-special characters, one at a time (they change quote style).
for (const cp of [0x27, 0x22, 0x5c, 0x2e]) {
  const r = run(String.fromCodePoint(cp), 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`C ${hex(cp)} -> raw=${lit ? JSON.stringify(lit.raw) : 'UNPARSED ' + JSON.stringify(r.out.slice(0,120))}`);
}

// D: can U+0000 even be passed through argv?
{
  const r = run('a�b', 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`D NUL-in-arg: code=${r.code} body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'} err=${JSON.stringify(r.err.slice(-300))}`);
}
{
  const r = run('�', 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`D NUL-alone: code=${r.code} body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'} err=${JSON.stringify(r.err.slice(-300))}`);
}

// E: lone surrogates
for (const cu of [0xd800, 0xdc00, 0xdfff]) {
  const s = 'X' + String.fromCharCode(cu) + 'Y';
  const r = run(s, 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`E lone ${hex(cu)}: code=${r.code} body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'} err=${JSON.stringify(r.err.slice(-200))}`);
}

// F: astral survival
{
  const r = run('[\u{1F600}\u{10FFFF}\u{F0000}\u{E0001}]', 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`F astral: body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'}`);
}

// G: env/locale sanity -- how many bytes does the exe see for a 2-byte char?
{
  const r = run('ééé', 'MARKER');
  const lit = oldValueLit(r.out);
  console.log(`G eee: body=${lit ? JSON.stringify(lit.body) : 'UNPARSED'} len=${lit ? lit.body.length : -1}`);
}

// Step 2: full dense sweep of the BMP (U+0001..U+FFFF, minus surrogates).
import { run } from './drv.mjs';
import { classifyBatch, jsPred, hex } from './esclib.mjs';
import { writeFileSync } from 'node:fs';

// Expected repr escape forms for a non-printable cp (lowercase hex).
function expectedEscapes(cp) {
  const out = [];
  if (cp === 0x09) out.push('\\t');
  if (cp === 0x0a) out.push('\\n');
  if (cp === 0x0d) out.push('\\r');
  if (cp <= 0xff) out.push('\\x' + cp.toString(16).padStart(2, '0'));
  else if (cp <= 0xffff) out.push('\\u' + cp.toString(16).padStart(4, '0'));
  else out.push('\\U' + cp.toString(16).padStart(8, '0'));
  return out;
}

// 'literal' | 'escaped' | 'mangled'
export function verdict(cp, field) {
  if (field === String.fromCodePoint(cp)) return 'literal';
  if (expectedEscapes(cp).includes(field)) return 'escaped';
  return 'mangled';
}

const EXCLUDE = new Set([0x00, 0x22, 0x27, 0x2e, 0x5c]); // sep + quote/backslash specials
function skip(cp) {
  return EXCLUDE.has(cp) || (cp >= 0xd800 && cp <= 0xdfff);
}

const all = [];
for (let cp = 0x0001; cp <= 0xffff; cp++) if (!skip(cp)) all.push(cp);

const BATCH = 2000;
const results = new Map(); // cp -> verdict
const mangled = [];
const disagree = [];
let runs = 0;

function classifyRobust(cps) {
  const res = classifyBatch(cps);
  runs++;
  if (!res.error) {
    for (let i = 0; i < cps.length; i++) {
      const cp = cps[i];
      const v = verdict(cp, res.fields[i]);
      results.set(cp, v);
      if (v === 'mangled') mangled.push([cp, res.fields[i]]);
      else {
        const isPrintable = v === 'literal';
        if (isPrintable !== jsPred(cp)) disagree.push([cp, isPrintable, jsPred(cp), res.fields[i]]);
      }
    }
    return;
  }
  if (cps.length === 1) {
    results.set(cps[0], 'ERR:' + res.error);
    mangled.push([cps[0], 'ERR:' + res.error + ' ' + JSON.stringify(res).slice(0, 160)]);
    return;
  }
  const mid = cps.length >> 1;
  classifyRobust(cps.slice(0, mid));
  classifyRobust(cps.slice(mid));
}

const t0 = Date.now();
for (let i = 0; i < all.length; i += BATCH) {
  classifyRobust(all.slice(i, i + BATCH));
  process.stderr.write(`\r${i + BATCH}/${all.length} runs=${runs} disagree=${disagree.length} mangled=${mangled.length} ${((Date.now()-t0)/1000).toFixed(0)}s`);
}
process.stderr.write('\n');

console.log(`\n=== BMP sweep done: ${results.size} code points, ${runs} exe runs, ${((Date.now()-t0)/1000).toFixed(1)}s`);
console.log(`literal=${[...results.values()].filter(v=>v==='literal').length} escaped=${[...results.values()].filter(v=>v==='escaped').length}`);
console.log(`\n=== MANGLED (${mangled.length}) ===`);
for (const [cp, f] of mangled.slice(0, 200)) console.log(`  ${hex(cp)} -> ${JSON.stringify(f)}`);

console.log(`\n=== DISAGREEMENTS (${disagree.length}) ===`);
for (const [cp, exe, js, f] of disagree) {
  console.log(`  ${hex(cp)} exePrintable=${exe} jsPred=${js} field=${JSON.stringify(f)}`);
}

writeFileSync('/workspace/probe/esc_bmp.json', JSON.stringify({
  results: [...results].map(([cp, v]) => [cp, v]),
  disagree, mangled,
}));

// Step 3: full dense sweep of the astral planes U+10000..U+10FFFF.
import { classifyBatch, jsPred, hex } from './esclib.mjs';
import { writeFileSync } from 'node:fs';

function expectedEscape(cp) {
  if (cp <= 0xff) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp <= 0xffff) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}
function verdict(cp, field) {
  if (field === String.fromCodePoint(cp)) return 'literal';
  if (field === expectedEscape(cp)) return 'escaped';
  return 'mangled';
}

const BATCH = 12000;
const disagree = [];
const mangled = [];
