  const cps = [];
  for (let cp = start; cp < Math.min(start + BATCH, 0x110000); cp++) cps.push(cp);
  classifyRobust(cps);
  process.stderr.write(`\r${hex(start)} n=${n} runs=${runs} disagree=${disagree.length} mangled=${mangled.length} ${((Date.now()-t0)/1000).toFixed(0)}s`);
