for (const r of ranges) {
  console.log(`  ${hex(r.lo)}${r.lo !== r.hi ? '..' + hex(r.hi) : ''}  (${r.hi - r.lo + 1})  exePrintable=${r.exeP} jsPred=${r.jsP}`);
